{
    "Handling & Packaging Upcharges (continued)": {
      "Crate Pack Option": {
        "Description": [
          "Robust packaging option used to mitigate potential damage arising from shipping.",
          "Available for doors and drawer fronts only, this option must be requested by the customer.",
          "Available on 63\" x 45\" pallet only. Doors and drawer fronts up to 60\" in one dimension cannot exceed 42\" in the other dimension.",
          "Net charge of $58.00 per pallet."
        ],
        "Charges": {
          "30 to 250 pieces": "one pallet charge",
          "251 to 500 pieces": "two pallet charges",
          "501 to 750 pieces": "three pallet charges",
          "751 to 1,000 pieces": "four pallet charges"
        }
      }
    },
    "Drawer Box and Cabinet Systems Orders": {
      "Shipping Instructions": "If you are located in the following states: AL, FL, GA, MS, NC, SC or TN your order will ship from our Kenly, NC facility, all others will ship from our East Earl, PA location.",
      "Expedites": "Expedites will ship direct from our Kenly, NC facility. These costs are the responsibility of the customer."
    },
    "Conestoga Freight Terms": {
      "Open Credit Terms": [
        "Customers with open credit terms will be shipped prepaid via common carriers. A \"freight only\" invoice will be generated per delivery. Rates vary by zone and weight.",
        "All orders that ship via Conestoga route truck service will be consolidated and one \"freight only\" invoice will be generated per delivery. Rates vary by zone and weight.",
        "FedEx Ground and UPS Ground will be shipped prepaid and the charges will be added to each invoice."
      ],
      "100% Prepay": [
        "Customers will be charged for shipping at the time the order is placed.",
        "Conestoga will estimate the weight of the order and utilize a zone freight matrix to determine freight charges."
      ]
    },
    "Customer Pickup": {
      "Handling Fee": [
        "A 2.5% handling fee (min. $10.00 net) is added to all customer pickup orders due to staging, storage and double handling of the product. All customer pick-ups must be scheduled through Customer Service at least four business hours prior to the desired pickup time. Customers picking up their own orders are asked to do so within three days of the acknowledged ship date."
      ],
      "Warehouse Hours": "Warehouse hours of operation are 7:00 a.m. - 3:30 p.m. (EST), Monday through Friday."
    },
    "Damaged and Defective Product Policies": {
      "Instructions": [
        "Notify Customer Service in writing, within 12 business days after receipt of shipment, if you receive products that are damaged, defective or in error. Submitted claims must include the following information:",
        "Original order and line numbers.",
        "A list of the defects or errors in the product(s)."
      ],
      "Returns": "Returns of non-defective merchandise will not be accepted."
    }
  }

